// Ambient types for the Telegram Serverless runtime modules (provided by the platform, not npm).
declare module 'sdk' {
  export const api: any;
  export const db: any;
  export const fetch: any;
}
declare module 'sdk/db' {
  export const sql: any;
}
// Virtual module generated by scripts/build-platform.mjs (per-environment constants).
declare module 'platform-env' {
  const env: Record<string, string>;
  export default env;
}
